(function () {
      window.HLUI = window.HLUI || {};
      let SPA, Floater, Log, IBx, SBtn;

      window.HLUI_INIT = function () {
        SPA = document.getElementById('hl-spa-wrapper');
        Floater = document.getElementById('hl-floater');
        Log = document.getElementById('hl-story-log');
        IBx = document.getElementById('hl-input-box');
        SBtn = document.getElementById('hl-send-btn');
        if (!SPA || !Log) return false;

        const ensureBody = () => {
          if (SPA.parentElement && SPA.parentElement.tagName !== 'BODY') document.body.appendChild(SPA);
          if (Floater && Floater.parentElement && Floater.parentElement.tagName !== 'BODY')
            document.body.appendChild(Floater);
        };
        ensureBody();
        setInterval(ensureBody, 2000);

        HLUI.toggleSPA = show => {
          SPA.style.display = show ? 'flex' : 'none';
          if (Floater) Floater.style.display = show ? 'none' : 'block';
        };

        HLUI.togglePanel = id => {
          ['profile', 'task', 'inventory'].forEach(p => {
            const el = document.getElementById('hl-panel-' + p);
            if (el) el.classList.toggle('open', p === id);
          });
        };

        HLUI.sendCommand = txt => {
          if (!txt) return;
          const ta = document.getElementById('send_textarea');
          const bt = document.getElementById('send_but');
          if (ta && bt) {
            ta.value = txt;
            ta.dispatchEvent(new Event('input', { bubbles: true }));
            bt.click();
          }
        };

        if (SBtn)
          SBtn.onclick = () => {
            HLUI.sendCommand(IBx.value);
            IBx.value = '';
          };

        // --- MVU Integration ---
        function getNested(obj, path) {
          return path.split('.').reduce((prev, curr) => (prev ? prev[curr] : undefined), obj);
        }

        function refreshUI() {
          if (SPA.style.display === 'none') return;
          const M = window.Mvu;
          const ST = window.SillyTavern || window.ST;
          if (!M || !ST) return;
          const data = M.getMvuData ? M.getMvuData() : {};

          SPA.querySelectorAll('.hl-live-var').forEach(el => {
            const path = el.getAttribute('data-var');
            let val = getNested(data, path);
            if (val === undefined) val = ST.getContext().substituteParams('{{getvar::' + path + '}}');
            if (typeof val === 'object') val = JSON.stringify(val, null, 2);
            if (el.innerText !== String(val)) el.innerText = val;
          });

          const hp = parseInt(getNested(data, '主角.体力值.当前值')) || 100;
          const san = parseInt(getNested(data, '主角.精神值.当前值')) || 100;
          document.getElementById('hl-bar-hp').style.width = hp + '%';
          document.getElementById('hl-bar-san').style.width = san + '%';
        }

        setInterval(refreshUI, 1000);
        if (window.eventOn && window.Mvu && window.Mvu.events) {
          eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, refreshUI);
        }

        // --- Chat & Command Hydration ---
        function hydrate(node) {
          const text = node.innerText || '';
          const cmds = text.match(/【[^】]+】/g);
          if (!cmds) return;
          const wrap = document.createElement('div');
          wrap.style.marginTop = '8px';
          [...new Set(cmds)].forEach(c => {
            const btn = document.createElement('button');
            btn.className = 'hl-cmd-btn';
            btn.innerText = c.replace(/[【】]/g, '');
            btn.onclick = () => HLUI.sendCommand(c);
            wrap.appendChild(btn);
          });
          node.appendChild(wrap);
        }

        const chatObs = new MutationObserver(muts => {
          const chat = document.getElementById('chat');
          if (!chat) return;
          Log.innerHTML = '';
          const messages = chat.querySelectorAll('.mes');
          messages.forEach(m => {
            if (m.querySelector('#hl-spa-wrapper')) return;
            const clone = m.cloneNode(true);
            const textNode = clone.querySelector('.mes_text');
            if (textNode) hydrate(textNode);
            Log.appendChild(clone);
          });
          Log.scrollTop = Log.scrollHeight;

          // Sidebar commands update
          const lastMes = messages[messages.length - 1];
          if (lastMes) {
            const sidebarNode = document.getElementById('hl-node-cmds');
            sidebarNode.innerHTML = '';
            const cmds = lastMes.innerText.match(/【[^】]+】/g);
            if (cmds)
              [...new Set(cmds)].forEach(c => {
                const btn = document.createElement('button');
                btn.className = 'hl-cmd-btn';
                btn.innerText = c;
                btn.onclick = () => HLUI.sendCommand(c);
                sidebarNode.appendChild(btn);
              });
          }
        });
        if (document.getElementById('chat'))
          chatObs.observe(document.getElementById('chat'), { childList: true, subtree: true });

        // --- Logic Initialization ---
        const ST = window.SillyTavern || window.ST;
        const isStarted =
          ST && ST.getContext && ST.getContext().chat
            ? ST.getContext().chat.length > 2
            : document.querySelectorAll('#chat .mes').length > 2;
        document.getElementById('hl-login-view').style.display = isStarted ? 'none' : 'flex';
        document.getElementById('hl-main-view').style.display = isStarted ? 'flex' : 'none';

        document.getElementById('hl-btn-confirm').onclick = () => {
          const n = document.getElementById('hl-inp-name').value;
          const d = document.getElementById('hl-inp-diff').value;
          const s = document.getElementById('hl-inp-nsfw').value;
          HLUI.sendCommand(`【入职申请】姓名：${n} | 难度：${d} | NSFW：${s}。请立即生成第一天工作简报！`);
          HLUI.toggleSPA(true);
        };

        return true;
      };

      const iInt = setInterval(() => {
        if (window.HLUI_INIT()) clearInterval(iInt);
      }, 500);
    })();

